294	     * two-digit country code. {@code null} when no telephone is set or the value is not in E.164
295	     * form. The raw {@link #getTelephone() telephone} is left in E.164 form. Not persisted —
296	     * derived from {@link #getTelephone()}.
297	     */
298	    @Transient
299	    public String getTelephoneDisplay() {
300	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
301	            return null;
302	        }
303	        String digits = this.telephone.substring(1);
304	        int countryCodeLength = digits.startsWith("1") && !digits.startsWith("61") ? 1 : 2;
305	        if (digits.length() <= countryCodeLength) {
306	            return this.telephone;
307	        }
308	        String countryCode = digits.substring(0, countryCodeLength);
309	        String national = digits.substring(countryCodeLength);
310	        StringBuilder grouped = new StringBuilder();
311	        for (int i = 0; i < national.length(); i++) {
312	            if (i > 0 && i % 3 == 0) {
313	                grouped.append(' ');
314	            }
315	            grouped.append(national.charAt(i));
316	        }
317	        return "+" + countryCode + " " + grouped;
318	    }
319	
320	    /**
321	     * The calendar year in which {@code date}'s fiscal year starts. The fiscal year starts on
322	     * 1 July, so a date in July–December belongs to the fiscal year starting that calendar year,
323	     * while a date in January–June belongs to the fiscal year that started the previous calendar
324	     * year.
325	     */
326	    private static int fiscalYearStart(LocalDate date) {
327	        return date.getMonthValue() >= 7 ? date.getYear() : date.getYear() - 1;
328	    }
329	
330	    /**
331	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where YY is the last two digits of the
332	     * calendar year in which the fiscal year starts (the fiscal year starts on 1 July), derived
333	     * from the business-day-adjusted {@link #getRegistrationDate() registrationDate}
334	     * (e.g. a registration date in October 2026 yields {@code 'FY26'}). Not persisted — derived
335	     * from {@link #getRegistrationDate()}.
336	     */
337	    @Transient
338	    public String getFiscalYear() {
339	        return "FY" + String.format("%02d", fiscalYearStart(this.registrationDate) % 100);
340	    }
341	
342	    /**
343	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is
344	     * the last two digits of the {@link #getFiscalYear() fiscal year} derived from the
345	     * business-day-adjusted {@link #getRegistrationDate() registrationDate}
346	     * (e.g. {@code 'NSW-1A2B3C4D-M26'}).
347	     * Not persisted — derived from {@link #getCustomerCode()} and {@link #getRegistrationDate()}.
348	     */
349	    @Transient
350	    public String getMembershipNumber() {
351	        return this.customerCode + "-M" + String.format("%02d", fiscalYearStart(this.registrationDate) % 100);
352	    }
353	
354	    /**
355	     * The owner's check digit: the Luhn check digit (0-9) computed over the digits contained
356	     * in the {@link #getCustomerCode() customerCode}. Non-digit characters are ignored.
357	     * Not persisted — derived from {@link #getCustomerCode()}.
358	     */
359	    @Transient
360	    public int getCheckDigit() {
361	        int sum = 0;
362	        boolean dbl = true;
363	        String code = this.customerCode == null ? "" : this.customerCode;
364	        for (int i = code.length() - 1; i >= 0; i--) {
365	            char c = code.charAt(i);
366	            if (c < '0' || c > '9') {
367	                continue;
368	            }
369	            int d = c - '0';
370	            if (dbl) {
371	                d *= 2;
372	                if (d > 9) {
373	                    d -= 9;
374	                }
375	            }
376	            sum += d;
377	            dbl = !dbl;
378	        }
379	        return (10 - (sum % 10)) % 10;
380	    }
381	
382	    /**
383	     * The owner's membership points. Starts at {@code 0}; adds {@code 2} when an
384	     * {@link #getEmail() email} is present; adds {@code 1} when {@link #getNamesakeCount()
385	     * namesakeCount} is {@code 0}; adds {@code 2} for a household of {@code 3} or more members
386	     * ({@link #getHouseholdSize() householdSize}); adds {@code 3} for a tenure of one or more
387	     * elapsed fiscal years since the {@link #getRegistrationDate() registration date}'s fiscal
388	     * year (the fiscal year starts on 1 July). Not persisted — derived from {@link #getEmail()},
389	     * {@link #getNamesakeCount()}, {@link #getHouseholdSize()} and {@link #getRegistrationDate()}.
390	     */
391	    @Transient
392	    public int getMembershipPoints() {
393	        int points = 0;
394	        boolean hasEmail = this.email != null && !this.email.isBlank();
395	        if (hasEmail) {
396	            points += 2;
397	        }
398	        boolean uniqueName = this.namesakeCount != null && this.namesakeCount == 0;
399	        if (uniqueName) {
400	            points += 1;
401	        }
402	        if (this.householdSize != null && this.householdSize >= 3) {
403	            points += 2;
404	        }
405	        if (this.registrationDate != null
406	                && fiscalYearStart(LocalDate.now()) - fiscalYearStart(this.registrationDate) >= 1) {
407	            points += 3;
408	        }
409	        return points;
410	    }
411	
412	    /**
413	     * The owner's numeric membership level, mapped from {@link #getMembershipPoints()
414	     * membershipPoints}: {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3},
415	     * {@code 3} for {@code 4-5} and {@code 4} for {@code 6} or more, then capped at
416	     * {@link #getMembershipLevelCap() membershipLevelCap} when one applies (a new owner's level
417	     * cannot exceed one above the maximum level among its existing household members). Not
418	     * persisted — derived from {@link #getMembershipPoints()} and {@link #getMembershipLevelCap()}.
419	     */
420	    @Transient
421	    public int getMembershipLevel() {
422	        int points = getMembershipPoints();
423	        int level;
424	        if (points >= 6) {
425	            level = 4;
426	        }
427	        else if (points >= 4) {
428	            level = 3;
429	        }
430	        else if (points >= 2) {
431	            level = 2;
432	        }
433	        else {
434	            level = 1;
435	        }
436	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
437	            return this.membershipLevelCap;
438	        }
439	        return level;
440	    }
441	
442	    /**
443	     * The owner's segment, formatted {@code '<TIER>_<AREA>'}, one of {@code 'PREMIUM_METRO'},
444	     * {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}. TIER is
445	     * {@code 'PREMIUM'} when {@link #getMembershipLevel() membershipLevel} is 3 or more, otherwise
446	     * {@code 'STANDARD'}. AREA is {@code 'METRO'} when the {@link #getLocality() locality} is a known
447	     * region (NSW, VIC or QLD), otherwise {@code 'REGIONAL'}. Not persisted — derived from
448	     * {@link #getMembershipLevel()} and {@link #getLocality()}.
449	     */
450	    @Transient
451	    public String getOwnerSegment() {
452	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
453	        String area = isKnownRegion(getLocality()) ? "METRO" : "REGIONAL";
454	        return tier + "_" + area;
455	    }
456	
457	    /**
458	     * Fixed city-to-region table used as the fall-back when deriving an owner's region.
459	     */
460	    private static final Map<String, String> CITY_REGION = Map.of(
461	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
462	
463	    /**
464	     * Region -> inclusive 4-digit postcode range {low, high}, the primary source for
465	     * deriving an owner's region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
466	     */
467	    private static final Map<String, int[]> REGION_RANGE = Map.of(
468	        "NSW", new int[] {2000, 2099},
469	        "VIC", new int[] {3000, 3099},
470	        "QLD", new int[] {4000, 4099});
471	
472	    /**
473	     * Fixed region -> IANA timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne,
474	     * QLD->Australia/Brisbane), the single authority for {@link #getTimezone()}.
475	     */
476	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
477	        "NSW", "Australia/Sydney",
478	        "VIC", "Australia/Melbourne",
479	        "QLD", "Australia/Brisbane");
480	
481	    /**
482	     * The canonical region for a postcode/city pair, derived first from {@code postcode} by range
483	     * ({@link #regionForPostcode}), falling back to the fixed city table ({@link #regionForCity})
484	     * when the postcode is absent or in no known range, or {@code 'UNKNOWN'} when neither matches.
485	     * Preferring the postcode disambiguates cities that share a name. This is the REGION prefix of
486	     * the owner's {@link #getCustomerCode() customerCode}, so the create pipeline and
487	     * {@link #getLocality() locality} agree on it. The single authority on the region rule, reused
488	     * by the owner pipelines (e.g. postcode validation) rather than copied.
489	     */
490	    public static String regionFor(String postcode, String city) {
491	        String region = regionForPostcode(postcode);
492	        if (region != null) {
493	            return region;
494	        }
495	        String cityRegion = regionForCity(city);
496	        return cityRegion != null ? cityRegion : "UNKNOWN";
497	    }
498	
499	    /** The canonical region for a city by exact name match (Sydney->NSW, Melbourne->VIC,
500	     * Brisbane->QLD), or {@code null} when the city has no known region. */
501	    public static String regionForCity(String city) {
502	        return city == null ? null : CITY_REGION.get(city);
503	    }
504	
505	    /** Whether {@code region} is one of the known regions (NSW, VIC or QLD); {@code 'UNKNOWN'}
506	     * and any other value are not. Backed by {@link #REGION_RANGE}, the primary source for the
507	     * region set. */
508	    public static boolean isKnownRegion(String region) {
509	        return REGION_RANGE.containsKey(region);
510	    }
511	
512	    /** Region whose inclusive range contains the given postcode (NSW 2000-2099, VIC 3000-3099,
513	     * QLD 4000-4099), or {@code null} when the postcode is absent, not 4 digits, or in no known
514	     * range. */
515	    public static String regionForPostcode(String postcode) {
516	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
517	            return null;
518	        }
519	        int value = Integer.parseInt(postcode);
520	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
521	            int[] range = entry.getValue();
522	            if (value >= range[0] && value <= range[1]) {
523	                return entry.getKey();
524	            }
525	        }
526	        return null;
527	    }
528	
529	    /**
530	     * The owner's locality: the REGION prefix of the {@link #getCustomerCode() customerCode}
531	     * (the portion before the first {@code '-'}), which the create pipeline derives from the
532	     * postcode-and-city region. {@code 'UNKNOWN'} when no customerCode is set. Not persisted —
533	     * derived from {@link #getCustomerCode()}.
534	     */
535	    @Transient
536	    public String getLocality() {
537	        if (this.customerCode == null) {
538	            return "UNKNOWN";
539	        }
540	        int dash = this.customerCode.indexOf('-');
541	        return dash <= 0 ? "UNKNOWN" : this.customerCode.substring(0, dash);
542	    }
543	
544	    /**
545	     * The owner's timezone: the IANA name for the owner's {@link #getLocality() locality}/region
546	     * from the fixed region-to-timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne,
547	     * QLD->Australia/Brisbane), or {@code null} when the region has no mapped timezone. Not
548	     * persisted — derived from {@link #getLocality()}.
549	     */
550	    @Transient
551	    public String getTimezone() {
552	        return REGION_TIMEZONE.get(getLocality());
553	    }
554	
555	    /**
556	     * Whether more than 80 owners had already been created today when this response was
557	     * built. Not persisted — populated for the response by the create and fetch pipelines
558	     * and defaults to {@code false} so every owner serialization carries the flag.
559	     */
560	    @Transient
561	    public boolean isBulkSignupWarning() {
562	        return this.bulkSignupWarning;
563	    }
564	
565	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
566	        this.bulkSignupWarning = bulkSignupWarning;
567	    }
568	
569	    /**
570	     * Whether this owner's city already held between 40 and 49 owners when this response was
571	     * built, approaching the hard capacity limit of 50 (compared case-insensitively). Not
572	     * persisted — populated for the response by the create and fetch pipelines and defaults to
573	     * {@code false} so every owner serialization carries the flag.
574	     */
575	    @Transient
576	    public boolean isCapacityWarning() {
577	        return this.capacityWarning;
578	    }
579	
580	    public void setCapacityWarning(boolean capacityWarning) {
581	        this.capacityWarning = capacityWarning;
582	    }
583	
584	    /**
585	     * Whether this owner is a possible (soft) duplicate: not a hard duplicate, but shares an
586	     * existing owner's last name and postcode with a different telephone. Not persisted —
587	     * populated for the response by the create and fetch pipelines and defaults to
588	     * {@code false} so every owner serialization carries the flag.
589	     */
590	    @Transient
591	    public boolean isPossibleDuplicate() {
592	        return this.possibleDuplicate;
593	    }
594	
595	    public void setPossibleDuplicate(boolean possibleDuplicate) {
596	        this.possibleDuplicate = possibleDuplicate;
597	    }
598	
599	    /**
600	     * The id of the existing owner this owner possibly duplicates (shared last name and
601	     * postcode, different telephone), or {@code null} when it is not a possible duplicate.
602	     * Not persisted — populated for the response alongside {@link #isPossibleDuplicate()}.
603	     */
604	    @Transient
605	    public Integer getPossibleDuplicateOf() {
606	        return this.possibleDuplicateOf;
607	    }
608	
609	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
610	        this.possibleDuplicateOf = possibleDuplicateOf;
611	    }
612	
613	    /**
614	     * The owner's preferred contact channel: {@code 'EMAIL'} when an {@link #getEmail() email}
615	     * is present, otherwise {@code 'PHONE'}.
616	     * Not persisted — derived from {@link #getEmail()}.
617	     */
618	    @Transient
619	    public String getContactPreference() {
620	        boolean hasEmail = this.email != null && !this.email.isBlank();
621	        return hasEmail ? "EMAIL" : "PHONE";
622	    }
623	
624	    /**
625	     * The owner's age band as of the {@link #getRegistrationDate() registrationDate}, derived
626	     * from {@link #getBirthDate() birthDate}: {@code 'MINOR'} when under 18, {@code 'ADULT'} for
627	     * 18 to 64 inclusive, {@code 'SENIOR'} for 65 and over. {@code null} when no birthDate is
628	     * supplied. Not persisted — derived from {@link #getBirthDate()} and
629	     * {@link #getRegistrationDate()}.
630	     */
631	    @Transient
632	    public String getAgeBand() {
633	        if (this.birthDate == null || this.registrationDate == null) {
634	            return null;
635	        }
636	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
637	        if (age < 18) {
638	            return "MINOR";
639	        }
640	        return age < 65 ? "ADULT" : "SENIOR";
641	    }
642	
643	    protected Set<Pet> getPetsInternal() {
644	        if (this.pets == null) {
645	            this.pets = new HashSet<>();
646	        }
647	        return this.pets;
648	    }
649	
650	    protected void setPetsInternal(Set<Pet> pets) {
651	        this.pets = pets;
652	    }
653	
654	    public List<Pet> getPets() {
655	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
656	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
657	        return Collections.unmodifiableList(sortedPets);
658	    }
659	
660	    public void setPets(List<Pet> pets) {
661	        this.pets = new HashSet<>(pets);
662	    }
663	
664	    public void addPet(Pet pet) {
665	        getPetsInternal().add(pet);
666	        pet.setOwner(this);
667	    }
668	
669	    /**
670	     * Return the Pet with the given name, or null if none found for this Owner.
671	     *
672	     * @param name to test
673	     * @return true if pet name is already in use
674	     */
675	    public Pet getPet(String name) {
676	        return getPet(name, false);
677	    }
678	
679	    /**
680	     * Return the Pet with the given name, or null if none found for this Owner.
681	     *
682	     * @param name to test
683	     * @return true if pet name is already in use
684	     */
685	    public Pet getPet(String name, boolean ignoreNew) {
686	        name = name.toLowerCase();
687	        for (Pet pet : getPetsInternal()) {
688	            if (!ignoreNew || !pet.isNew()) {
689	                String compName = pet.getName();
690	                compName = compName.toLowerCase();
691	                if (compName.equals(name)) {
692	                    return pet;
693	                }
694	            }
695	        }
696	        return null;
697	    }
698	
699	    public Pet getPet(Integer petId) {
700	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
701	    }
702	
703	    @Override
704	    public String toString() {
705	        return new ToStringCreator(this)
706	
707	            .append("id", this.getId())
708	            .append("new", this.isNew())
709	            .append("lastName", this.getLastName())
710	            .append("firstName", this.getFirstName())
711	            .append("address", this.address)
712	            .append("city", this.city)
713	            .append("telephone", this.telephone)
714	            .toString();
715	    }
716	}
