9	/**
10	 * Derives an owner's identity key — the single key that both gates duplicate detection and
11	 * populates the informational {@code identityKey} response field. The key is the lower-case
12	 * SHA-256 hex digest of {@code normalizedTelephone + "|" + lowerEmail + "|" + soundex(lastName)}.
13	 *
14	 * <p>Because the telephone is part of the key, two owners sharing a last name and postcode but
15	 * carrying different telephones derive different keys: they are no longer a hard duplicate, but a
16	 * soft match (see {@link PossibleDuplicate}). The duplicate gate ({@link ValidateUniqueIdentity})
17	 * rejects a create with a 409 only when an existing active owner carries the identical key.
18	 */
19	public final class OwnerIdentity {
20	
21	    private OwnerIdentity() {
22	    }
23	
24	    /**
25	     * Build the identity key from already-normalized parts: a normalized E.164 telephone, a
26	     * lower-cased email (or {@code null}) and a last name. A {@code null} telephone or email
27	     * segment is rendered as empty; the last name is reduced to its {@link Soundex} code.
28	     */
29	    static String key(String normalizedTelephone, String email, String lastName) {
30	        String seed = orEmpty(normalizedTelephone) + "|" + orEmpty(email) + "|" + Soundex.encode(lastName);
31	        return sha256hex(seed);
32	    }
33	
34	    /**
35	     * The identity key for the given raw parts, normalizing the telephone and email first so the
36	     * result compares identically whether built from a request body or an existing owner.
37	     */
38	    static String of(String telephone, String email, String lastName) {
39	        return key(OwnerTelephone.normalize(telephone), OwnerEmail.normalize(email), lastName);
40	    }
41	
42	    /**
43	     * The identity key of an owner, re-deriving the normalized telephone and email from the stored
44	     * values so it compares identically to a freshly built key and can be derived at the
45	     * Owner-to-DTO boundary for any response.
46	     */
47	    public static String of(Owner owner) {
48	        return of(owner.getTelephone(), owner.getEmail(), owner.getLastName());
49	    }
50	
51	    private static String orEmpty(String value) {
52	        return value == null ? "" : value;
53	    }
54	
55	    /** Full lower-case hex SHA-256 of the UTF-8 bytes of {@code seed}. */
56	    private static String sha256hex(String seed) {
57	        try {
58	            byte[] digest = MessageDigest.getInstance("SHA-256")
59	                    .digest(seed.getBytes(StandardCharsets.UTF_8));
60	            StringBuilder sb = new StringBuilder(digest.length * 2);
61	            for (byte b : digest) {
62	                sb.append(String.format("%02x", b));
63	            }
64	            return sb.toString();
65	        }
66	        catch (NoSuchAlgorithmException ex) {
67	            throw new IllegalStateException("SHA-256 not available", ex);
68	        }
69	    }
70	}
