11	
12	/**
13	 * Emits audit side effects for each successful owner create, keeping them out of the responder.
14	 * Runs after the owner is saved (so the id is populated) and before the responder.
15	 *
16	 * <p>Two things are emitted on the dedicated {@code AUDIT} channel:
17	 * <ol>
18	 * <li>a human-readable audit line carrying the owner id, the customerCode, the registrationDate,
19	 * the membershipLevel and the membershipNumber; and</li>
20	 * <li>an immutable structured {@link OwnerCreatedEvent} rendered as single-line JSON, carrying a
21	 * monotonically increasing {@code seq}, the owner id, the owner's current primary identifier and
22	 * its membershipLevel.</li>
23	 * </ol>
24	 */
25	public class AuditOwnerCreated {
26	
27	    /** Dedicated audit channel; one line per successful create. */
28	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
29	
30	    /** Source of the structured event's monotonically increasing {@code seq}, across all creates. */
31	    private static final AtomicLong SEQUENCE = new AtomicLong();
32	
33	    public void service(@Val Owner owner, ObjectMapper objectMapper) {
34	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
35	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
36	                owner.getMembershipLevel(), owner.getMembershipNumber());
37	
38	        // customerCode is the owner's current primary identifier (see OwnerCreatedEvent).
39	        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQUENCE.incrementAndGet(), owner.getId(),
40	                owner.getCustomerCode(), owner.getMembershipLevel());
41	        AUDIT.info(objectMapper.writeValueAsString(event));
42	    }
43	}
