457	    /**
458	     * Fixed city-to-region table used as the fall-back when deriving an owner's region.
459	     */
460	    private static final Map<String, String> CITY_REGION = Map.of(
461	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
462	
463	    /**
464	     * Region -> inclusive 4-digit postcode range {low, high}, the primary source for
465	     * deriving an owner's region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
466	     */
467	    private static final Map<String, int[]> REGION_RANGE = Map.of(
468	        "NSW", new int[] {2000, 2099},
469	        "VIC", new int[] {3000, 3099},
470	        "QLD", new int[] {4000, 4099});
471	
472	    /**
473	     * Fixed region -> IANA timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne,
474	     * QLD->Australia/Brisbane), the single authority for {@link #getTimezone()}.
475	     */
476	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
477	        "NSW", "Australia/Sydney",
478	        "VIC", "Australia/Melbourne",
479	        "QLD", "Australia/Brisbane");
480	
481	    /**
482	     * The canonical region for a postcode/city pair, derived first from {@code postcode} by range
483	     * ({@link #regionForPostcode}), falling back to the fixed city table ({@link #regionForCity})
484	     * when the postcode is absent or in no known range, or {@code 'UNKNOWN'} when neither matches.
485	     * Preferring the postcode disambiguates cities that share a name. This is the REGION prefix of
486	     * the owner's {@link #getCustomerCode() customerCode}, so the create pipeline and
487	     * {@link #getLocality() locality} agree on it. The single authority on the region rule, reused
488	     * by the owner pipelines (e.g. postcode validation) rather than copied.
489	     */
490	    public static String regionFor(String postcode, String city) {
491	        String region = regionForPostcode(postcode);
492	        if (region != null) {
493	            return region;
494	        }
495	        String cityRegion = regionForCity(city);
496	        return cityRegion != null ? cityRegion : "UNKNOWN";
497	    }
498	
499	    /** The canonical region for a city by exact name match (Sydney->NSW, Melbourne->VIC,
500	     * Brisbane->QLD), or {@code null} when the city has no known region. */
501	    public static String regionForCity(String city) {
502	        return city == null ? null : CITY_REGION.get(city);
503	    }
504	
505	    /** Whether {@code region} is one of the known regions (NSW, VIC or QLD); {@code 'UNKNOWN'}
506	     * and any other value are not. Backed by {@link #REGION_RANGE}, the primary source for the
507	     * region set. */
508	    public static boolean isKnownRegion(String region) {
509	        return REGION_RANGE.containsKey(region);
510	    }
511	
512	    /** Region whose inclusive range contains the given postcode (NSW 2000-2099, VIC 3000-3099,
513	     * QLD 4000-4099), or {@code null} when the postcode is absent, not 4 digits, or in no known
514	     * range. */
515	    public static String regionForPostcode(String postcode) {
516	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
517	            return null;
518	        }
519	        int value = Integer.parseInt(postcode);
520	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
521	            int[] range = entry.getValue();
522	            if (value >= range[0] && value <= range[1]) {
523	                return entry.getKey();
524	            }
525	        }
526	        return null;
527	    }
