529	    /**
530	     * The owner's locality: the REGION prefix of the {@link #getCustomerCode() customerCode}
531	     * (the portion before the first {@code '-'}), which the create pipeline derives from the
532	     * postcode-and-city region. {@code 'UNKNOWN'} when no customerCode is set. Not persisted —
533	     * derived from {@link #getCustomerCode()}.
534	     */
535	    @Transient
536	    public String getLocality() {
537	        if (this.customerCode == null) {
538	            return "UNKNOWN";
539	        }
540	        int dash = this.customerCode.indexOf('-');
541	        return dash <= 0 ? "UNKNOWN" : this.customerCode.substring(0, dash);
542	    }
