586	     * existing owner's last name and postcode with a different telephone. Not persisted —
587	     * populated for the response by the create and fetch pipelines and defaults to
588	     * {@code false} so every owner serialization carries the flag.
589	     */
590	    @Transient
591	    public boolean isPossibleDuplicate() {
592	        return this.possibleDuplicate;
593	    }
594	
595	    public void setPossibleDuplicate(boolean possibleDuplicate) {
596	        this.possibleDuplicate = possibleDuplicate;
597	    }
598	
599	    /**
600	     * The id of the existing owner this owner possibly duplicates (shared last name and
601	     * postcode, different telephone), or {@code null} when it is not a possible duplicate.
602	     * Not persisted — populated for the response alongside {@link #isPossibleDuplicate()}.
603	     */
604	    @Transient
605	    public Integer getPossibleDuplicateOf() {
606	        return this.possibleDuplicateOf;
607	    }
608	
609	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
610	        this.possibleDuplicateOf = possibleDuplicateOf;
611	    }
612	
613	    /**
614	     * The owner's preferred contact channel: {@code 'EMAIL'} when an {@link #getEmail() email}
615	     * is present, otherwise {@code 'PHONE'}.
616	     * Not persisted — derived from {@link #getEmail()}.
617	     */
618	    @Transient
619	    public String getContactPreference() {
620	        boolean hasEmail = this.email != null && !this.email.isBlank();
621	        return hasEmail ? "EMAIL" : "PHONE";
622	    }
623	
624	    /**
625	     * The owner's age band as of the {@link #getRegistrationDate() registrationDate}, derived
626	     * from {@link #getBirthDate() birthDate}: {@code 'MINOR'} when under 18, {@code 'ADULT'} for
627	     * 18 to 64 inclusive, {@code 'SENIOR'} for 65 and over. {@code null} when no birthDate is
628	     * supplied. Not persisted — derived from {@link #getBirthDate()} and
629	     * {@link #getRegistrationDate()}.
630	     */
631	    @Transient
632	    public String getAgeBand() {
633	        if (this.birthDate == null || this.registrationDate == null) {
634	            return null;
635	        }
636	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
637	        if (age < 18) {
638	            return "MINOR";
639	        }
640	        return age < 65 ? "ADULT" : "SENIOR";
641	    }
642	
643	    protected Set<Pet> getPetsInternal() {
644	        if (this.pets == null) {
645	            this.pets = new HashSet<>();
646	        }
647	        return this.pets;
648	    }
649	
650	    protected void setPetsInternal(Set<Pet> pets) {
651	        this.pets = pets;
652	    }
653	
654	    public List<Pet> getPets() {
655	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
656	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
657	        return Collections.unmodifiableList(sortedPets);
658	    }
659	
660	    public void setPets(List<Pet> pets) {
661	        this.pets = new HashSet<>(pets);
662	    }
663	
664	    public void addPet(Pet pet) {
665	        getPetsInternal().add(pet);
666	        pet.setOwner(this);
667	    }
668	
669	    /**
670	     * Return the Pet with the given name, or null if none found for this Owner.
671	     *
672	     * @param name to test
673	     * @return true if pet name is already in use
674	     */
675	    public Pet getPet(String name) {
676	        return getPet(name, false);
677	    }
678	
679	    /**
680	     * Return the Pet with the given name, or null if none found for this Owner.
681	     *
682	     * @param name to test
683	     * @return true if pet name is already in use
684	     */
685	    public Pet getPet(String name, boolean ignoreNew) {
686	        name = name.toLowerCase();
687	        for (Pet pet : getPetsInternal()) {
688	            if (!ignoreNew || !pet.isNew()) {
689	                String compName = pet.getName();
690	                compName = compName.toLowerCase();
691	                if (compName.equals(name)) {
692	                    return pet;
693	                }
694	            }
695	        }
696	        return null;
697	    }
698	
699	    public Pet getPet(Integer petId) {
700	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
701	    }
702	
703	    @Override
704	    public String toString() {
705	        return new ToStringCreator(this)
706	
707	            .append("id", this.getId())
708	            .append("new", this.isNew())
709	            .append("lastName", this.getLastName())
710	            .append("firstName", this.getFirstName())
711	            .append("address", this.address)
712	            .append("city", this.city)
713	            .append("telephone", this.telephone)
714	            .toString();
715	    }
716	}
