2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * The single duplicate-detection gate of {@code POST /api/owners}, running before {@link BuildOwner}.
11	 * Duplicate detection is now the one identity key (see {@link OwnerIdentity}): the create is rejected
12	 * with a 409 when an existing active owner carries the identical identity key, derived from the
13	 * request's normalized telephone, lower-cased email and {@link Soundex soundex} of the last name.
14	 *
15	 * <p>The scan ignores owners flagged soft-deleted (see {@link ActiveOwners}), and the email-domain
16	 * blocklist is applied earlier in {@link ValidateNewOwner}, so a disposable-domain email is a 400
17	 * before this gate runs. Because the telephone is part of the key, two owners with the same last
18	 * name and postcode but different telephones are no longer a hard duplicate — they are created and
19	 * surfaced as a soft match (see {@link PossibleDuplicate}). Publishes nothing; it only escalates on
20	 * conflict.
21	 */
22	public class ValidateUniqueIdentity {
23	
24	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
25	            throws DuplicateIdentityException {
26	        String key = OwnerIdentity.of(request.getTelephone(), request.getEmail(), request.getLastName());
27	        for (Owner existing : ActiveOwners.list(ownerRepository)) {
28	            if (key.equals(OwnerIdentity.of(existing))) {
29	                throw new DuplicateIdentityException(
30	                        "An owner with the same identity key already exists: " + key);
31	            }
32	        }
33	    }
34	}
