1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	import java.util.OptionalInt;
8	
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.repository.OwnerRepository;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	
13	/**
14	 * Shared household rules for the owner-create pipeline. A household is now keyed on
15	 * {@code (lastName, postcode)}: every owner with a postcode derives a deterministic
16	 * {@link Id} from its normalized last name and postcode, so owners with the same last name
17	 * and postcode share the same id automatically, regardless of creation order. The id is
18	 * defined once here so the resolver ({@link ResolveHousehold}) and the new owner
19	 * ({@link BuildOwner}) agree on it; it groups owners for the household-size and membership-level
20	 * rules but no longer gates duplicate detection, which is now the single owner identity key
21	 * ({@link OwnerIdentity}).
22	 */
23	final class Household {
24	
25	    private Household() {
26	    }
27	
28	    /**
29	     * The household identifier published between steps. A dedicated type keeps the variable
30	     * unambiguous (OfficeFloor matches variables by type) and distinct from other strings in
31	     * the pipeline. {@link #ABSENT} (an empty value) means the new owner has no postcode and
32	     * therefore no household.
33	     */
34	    record Id(String value) {
35	
36	        static final Id ABSENT = new Id("");
37	
38	        boolean isPresent() {
39	            return this.value != null && !this.value.isBlank();
40	        }
41	    }
42	
43	    /**
44	     * Stable identifier for the request's household: the first 12 upper-case hex characters of
45	     * the SHA-256 of {@code normalizedLastName + "|" + postcode}, so every owner with the same
46	     * last name and postcode derives the same value regardless of creation order.
47	     * {@link Id#ABSENT} when the request carries no postcode (no postcode means no household).
48	     */
49	    static Id idFor(OwnerFieldsDto request) {
50	        String postcode = normalizePostcode(request.getPostcode());
51	        if (postcode == null) {
52	            return Id.ABSENT;
53	        }
54	        String seed = normalizeName(request.getLastName()) + "|" + postcode;
55	        try {
56	            byte[] digest = MessageDigest.getInstance("SHA-256")
57	                    .digest(seed.getBytes(StandardCharsets.UTF_8));
58	            StringBuilder sb = new StringBuilder();
59	            for (int i = 0; i < 6; i++) {
60	                sb.append(String.format("%02X", digest[i]));
61	            }
62	            return new Id(sb.toString());
63	        }
64	        catch (NoSuchAlgorithmException ex) {
65	            throw new IllegalStateException("SHA-256 not available", ex);
66	        }
67	    }
68	
69	    /**
70	     * The number of owners carrying {@code householdId}. The single household-size lookup, reused
71	     * wherever the membership points rule needs a household's member count. {@code 0} for a
72	     * {@code null}/blank id (an owner with no postcode has no household). Scans only
73	     * {@link ActiveOwners active owners}, so a soft-deleted owner does not count towards a
74	     * household's size.
75	     */
76	    static int size(String householdId, OwnerRepository ownerRepository) {
77	        if (householdId == null || householdId.isBlank()) {
78	            return 0;
79	        }
80	        int count = 0;
81	        for (Owner existing : ActiveOwners.list(ownerRepository)) {
82	            if (householdId.equals(existing.getHouseholdId())) {
83	                count++;
84	            }
85	        }
86	        return count;
87	    }
88	
89	    /**
90	     * The maximum {@link Owner#getMembershipLevel() membershipLevel} among the members of
91	     * {@code householdId} other than {@code exclude}, or {@link OptionalInt#empty()} when the
92	     * household has no such member (so no cap applies). Each member's household size is resolved
93	     * first — exactly as {@link LoadOwner} does on read — so its level is scored on a fully
94	     * populated household rather than as a lone member. Scans only {@link ActiveOwners active
95	     * owners}, consistent with {@link #size}, so a soft-deleted owner does not raise the ceiling.
96	     * {@link OptionalInt#empty()} for a {@code null}/blank id.
97	     */
98	    static OptionalInt maxMemberLevel(String householdId, Owner exclude, OwnerRepository ownerRepository) {
99	        if (householdId == null || householdId.isBlank()) {
100	            return OptionalInt.empty();
101	        }
102	        int max = -1;
103	        for (Owner existing : ActiveOwners.list(ownerRepository)) {
104	            if (exclude != null && exclude.getId() != null && exclude.getId().equals(existing.getId())) {
105	                continue;
106	            }
107	            if (householdId.equals(existing.getHouseholdId())) {
108	                existing.setHouseholdSize(Math.max(1, size(householdId, ownerRepository)));
109	                max = Math.max(max, existing.getMembershipLevel());
110	            }
111	        }
112	        return max < 0 ? OptionalInt.empty() : OptionalInt.of(max);
113	    }
114	
115	    /**
116	     * Normalize a last name for the household key: trim, collapse any run of whitespace to a
117	     * single space, and lower-case. Yields {@code ""} for a {@code null} input.
118	     */
119	    private static String normalizeName(String value) {
120	        if (value == null) {
121	            return "";
122	        }
123	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
124	    }
125	
126	    /** Trimmed postcode, or {@code null} when absent/blank (no postcode means no household). */
127	    private static String normalizePostcode(String value) {
128	        if (value == null || value.isBlank()) {
129	            return null;
130	        }
131	        return value.trim();
132	    }
133	}
