package org.springframework.samples.petclinic.rest.function.owner;

import java.util.concurrent.atomic.AtomicLong;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import tools.jackson.databind.ObjectMapper;

/**
 * Emits audit side effects for each successful owner create, keeping them out of the responder.
 * Runs after the owner is saved (so the id is populated) and before the responder.
 *
 * <p>Two things are emitted on the dedicated {@code AUDIT} channel:
 * <ol>
 * <li>a human-readable audit line carrying the owner id, the memberId, the registrationDate,
 * the membershipLevel and the fiscalYear; and</li>
 * <li>an immutable structured {@link OwnerCreatedEvent} rendered as single-line JSON, carrying a
 * monotonically increasing {@code seq}, the owner id, the owner's current primary identifier and
 * its membershipLevel.</li>
 * </ol>
 */
public class AuditOwnerCreated {

    /** Dedicated audit channel; one line per successful create. */
    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    /** Source of the structured event's monotonically increasing {@code seq}, across all creates. */
    private static final AtomicLong SEQUENCE = new AtomicLong();

    public void service(@Val Owner owner, ObjectMapper objectMapper) {
        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
                owner.getMembershipLevel(), owner.getMembershipNumber());

        // customerCode is the owner's current primary identifier (see OwnerCreatedEvent).
        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQUENCE.incrementAndGet(), owner.getId(),
                owner.getCustomerCode(), owner.getMembershipLevel());
        AUDIT.info(objectMapper.writeValueAsString(event));
    }
}

input.old_string:
 * <p>Carries a monotonically increasing {@code seq}, the saved owner's {@code ownerId}, the owner's
 * current primary identifier and its {@code membershipLevel}, with a fixed {@code event} discriminator
 * of {@code OWNER_CREATED}.
 *
 * <p>The {@code customerCode} field holds the owner's <em>current primary identifier</em>. Today that
 * is the {@link org.springframework.samples.petclinic.model.Owner#getCustomerCode() customerCode}; when
 * a later checkpoint unifies the customerCode into a memberId, the same field carries the memberId
 * instead — the event always names whatever the current primary identifier is.
 *
 * <p>A pure data record: it is serialized to JSON by the audit step via the shared {@code ObjectMapper},
 * so the event renders the same way as every other DTO in the system.
 */
public record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode, Integer membershipLevel,
        String event) {

    /** The fixed discriminator for a successful owner create. */
    public static final String OWNER_CREATED = "OWNER_CREATED";

    public OwnerCreatedEvent(long seq, Integer ownerId, String customerCode, Integer membershipLevel) {
        this(seq, ownerId, customerCode, membershipLevel, OWNER_CREATED);
    }
}

